from lib import *
S = SS('k52')
F1 = [['k52-imm(Immediate)', 'Pending + ProvisioningFailed'], ['k52-wait(WaitForFirstConsumer)', 'Pending,等 Pod'], ['创建 Pod', '2.2 秒后 Bound'], ['PV', '带 nodeAffinity=worker3']]
F2 = [['WaitForFirstConsumer', ''], ['ExternalProvisioning', '等 provisioner'], ['Provisioning', 'rancher.io/local-path'], ['ProvisioningSucceeded', '3.2 秒内 Bound']]
F3 = [['不写 storageClassName', '补成默认类 standard'], ['storageClassName: ""', '不动态供给,Pending'], ['两个默认类', '选最新创建的 k52-default']]
F4 = [['存储类 reclaimPolicy: Retain', ''], ['供给出的 PV', '继承 Retain'], ['删 PVC', 'PV Released,数据还在']]
PANELS = [('f', 'flow', '动态供给'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("kind 自带一个 StorageClass:standard(default),provisioner rancher.io/local-path,reclaimPolicy Delete,volumeBindingMode WaitForFirstConsumer,allowVolumeExpansion false。自建 k52-imm(Immediate)与 k52-wait(WaitForFirstConsumer):没有 Pod 使用时两个 PVC 都是 Pending;Immediate 的那个有事件 ProvisioningFailed: … configuration error, no node was specified——local-path 在不知道节点时没法造卷;创建使用 p-wait 的 Pod 后 2.2 秒 PVC Bound,PV 的 nodeAffinity 就是 Pod 被调度的 kx-sched-worker3,PVC 注解里有 volume.kubernetes.io/selected-node。", f=fl(F1, cur=[0, 1, 2], done=[3]), t=tl(S(1), mark=lidx(S(1), 'ProvisioningFailed', 'p-imm(', 'p-wait('), done=lidx(S(1), '创建使用 p-wait')), kv=KV([['WaitForFirstConsumer', '等调度器选好节点,再在那里造卷'], ['Immediate', 'PVC 一创建就供给,provisioner 必须不依赖节点'], ['selected-node 注解', '调度器告诉 provisioner 选了哪个节点']], ['WaitForFirstConsumer'])),
    step("一次供给的事件序列(从创建使用它的 Pod 开始 3.2 秒 Bound):PVC 事件依次 WaitForFirstConsumer → ExternalProvisioning(等 provisioner 'rancher.io/local-path')→ Provisioning → ProvisioningSucceeded: Successfully provisioned volume pvc-…。PV:路径 /var/local-path-provisioner/pvc-…_k52_p2,storageClassName=k52-wait,reclaim=Delete,注解 pv.kubernetes.io/provisioned-by 与 local.path.provisioner/selected-node。", f=fl(F2, cur=[1, 2], done=[3]), t=tl(S(2), mark=lidx(S(2), 'ExternalProvisioning', 'Provisioning:'), done=lidx(S(2), 'ProvisioningSucceeded', '3.2 秒')), kv=KV([['外部供给', 'provisioner 是独立的控制器(这里是 local-path-provisioner)'], ['PV 是造出来的', '回填 storageClassName、reclaim、节点亲和'], ['事件', '排查供给失败先看 PVC 事件']], ['外部供给'])),
    step("没写 storageClassName:PVC nocls 被补成默认类 standard;storageClassName: \"\" 的 emptycls 保持空字符串、Pending(空串表示不要动态供给、只绑静态 PV);再把 k52-default 也标成默认类,集群里有 2 个默认类 [k52-default, standard],这时不写类的 PVC 拿到的是 k52-default(多个默认类时选最新创建的)。", f=fl(F3, cur=[0], mark=[1, 2]), t=tl(S(3), mark=lidx(S(3), 'emptycls', 'two-defaults'), done=lidx(S(3), 'nocls')), kv=KV([['不写 storageClassName', '准入补成默认类'], ['空字符串', '明确“不要动态供给”'], ['多个默认类', '含糊,最好只留一个']], ['空字符串'])),
    step("reclaimPolicy 写在存储类上,供给出来的 PV 继承:k52-keep(Retain)供给的 PV persistentVolumeReclaimPolicy=Retain;删掉 PVC 之后 PV 仍在、phase=Released,节点 worker4 上目录里的文件 f 内容还是 hello——数据还在。", f=fl(F4, cur=[1], done=[0, 2]), t=tl(S(4), mark=lidx(S(4), 'Released'), done=lidx(S(4), '存储类 k52-keep')), kv=KV([['reclaimPolicy', '存储类上的设置会被复制到 PV'], ['Retain', '删 PVC 后保留 PV 与数据,人工清理'], ['想改已有 PV', '直接改 PV 的 persistentVolumeReclaimPolicy']], ['reclaimPolicy'])),
]
A = mkartk('k52', 52, 'Kubernetes,StorageClass,动态供给,volumeBindingMode,默认存储类,reclaimPolicy,真实验证,动画演示',
    '在 kind 集群里实测 StorageClass 的动态供给:local-path 在 Immediate 模式下因不知道节点而 ProvisioningFailed,在 WaitForFirstConsumer 模式下等 Pod 调度后 2.2 秒 Bound 且 PV 带该节点的亲和;一次供给的事件序列 WaitForFirstConsumer → ExternalProvisioning → Provisioning → ProvisioningSucceeded(3.2 秒);不写 storageClassName 会被补成默认类,空字符串表示不动态供给,多个默认类时选最新的;存储类的 reclaimPolicy 被供给出的 PV 继承,Retain 时删 PVC 后数据仍在。',
    'PVC 是怎么变出一个 PV 的?Immediate 和 WaitForFirstConsumer 差在哪?不写 storageClassName 会怎样?这篇用 kind 自带的 local-path provisioner 把一次动态供给的每个环节(事件、注解、PV 的字段)都拆开看。',
    [('2.2 秒', '创建使用 WaitForFirstConsumer 类 PVC 的 Pod 之后,PVC 变成 Bound 的时间'), ('no node was specified', 'local-path 在 Immediate 模式下供给失败的原因'), ('2 个默认类', '同时标了两个默认 StorageClass 之后,不写类的 PVC 拿到的是最新创建的那个')],
    [('什么时候造卷', '<p>两个 PVC,一个用 <code>Immediate</code> 类、一个用 <code>WaitForFirstConsumer</code> 类,没有 Pod 使用时都 <code>Pending</code>。区别是 <code>Immediate</code> 的 PVC 一创建就让 provisioner 去造,而 local-path 造本地卷必须知道节点,于是失败:<code>ProvisioningFailed … configuration error, no node was specified</code>。<code>WaitForFirstConsumer</code> 的 PVC 等 Pod 被调度后:调度器在 PVC 上写下 <code>volume.kubernetes.io/selected-node</code> 注解,provisioner 在那个节点上造卷,2.2 秒后 <code>Bound</code>,PV 的 <code>nodeAffinity</code> 就是那个节点。</p>'),
     ('一次供给的事件', '<p>PVC 的事件依次是 <code>WaitForFirstConsumer</code> → <code>ExternalProvisioning</code>(等外部 provisioner <code>rancher.io/local-path</code> 来造)→ <code>Provisioning</code> → <code>ProvisioningSucceeded: Successfully provisioned volume pvc-…</code>,共 3.2 秒。PV 是 provisioner 造出来并回填字段的:路径 <code>/var/local-path-provisioner/pvc-…_k52_p2</code>,<code>storageClassName</code>、<code>reclaim</code> 来自存储类,注解 <code>pv.kubernetes.io/provisioned-by</code> 记着谁造的。供给失败时第一件事是看 PVC 的事件。</p>'),
     ('默认存储类', '<p>不写 <code>storageClassName</code> 的 PVC 在准入时被补成默认类(<code>standard</code>);写成空字符串 <code>""</code> 则明确表示“不要动态供给,只绑静态 PV”,没有静态 PV 就一直 Pending。再给 <code>k52-default</code> 也标上默认注解,集群里就有两个默认类,不写类的 PVC 拿到最新创建的那个——含糊,生产里应该只留一个。</p>'),
     ('回收策略继承', '<p><code>reclaimPolicy</code> 写在存储类上,供给出来的 PV 直接继承:<code>k52-keep</code>(Retain)供给的 PV 也是 <code>Retain</code>。删掉 PVC 之后 PV 变成 <code>Released</code>,节点上目录里的文件还是 <code>hello</code>,数据还在,要人工处理。standard 默认是 <code>Delete</code>,所以删 PVC 数据就没了。</p>')],
    steps,
    [ENV_K + '。独立的 5 节点 kind 集群 kx-sched(Kubernetes v1.37.0),存储是 kind 自带的 local-path-provisioner;自建的 StorageClass k52-imm / k52-wait / k52-keep / k52-default 与 PV、目录在实验后都已删除(Retain 的 PV 与节点上的目录手动清理);“Bound 用时”是 0.2~0.3 秒间隔轮询;PV 的 nodeAffinity 与 Pod 的 nodeName 取自对象;每种情形各一次',
     '没有验证:allowVolumeExpansion 与在线扩容(下一篇);mountOptions、parameters 的传递;volumeBindingMode 与 allowedTopologies;CSI 驱动与外部 provisioner 的 leader 选举;存储类的不可变字段(provisioner、parameters 修改会被拒绝);快照类(VolumeSnapshotClass);存储容量跟踪(CSIStorageCapacity)'],
    '动态供给', PANELS)
